// x87 status word bits of a compare: C0 below, C3 equal, C0|C2|C3 unordered
static inline DWORD x87_compare(double a, double b)
{
    if (a < b)
        return 0x0100;
    if (a == b)
        return 0x4000;
    if (a > b)
        return 0;
    return 0x4500;
}

